mapper.select:
SELECT a.*, c.category_name, u.real_name as seller_name, CASE a.condition_level WHEN 'EXCELLENT' THEN '优秀' WHEN 'GOOD' THEN '良好' WHEN 'FAIR' THEN '一般' WHEN 'POOR' THEN '较差' ELSE a.condition_level END as condition_level_desc, CASE a.status WHEN 'TO_REFURBISH' THEN '待翻新' WHEN 'REFURBISHING' THEN '翻新中' WHEN 'TO_SELL' THEN '待寄售' WHEN 'SOLD' THEN '已售出' ELSE a.status END as status_desc FROM instrument_archive a LEFT JOIN instrument_category c ON a.category_id = c.id LEFT JOIN sys_user u ON a.seller_id = u.id WHERE a.is_deleted = 0
AND a.category_id = #{query.categoryId}
AND a.brand LIKE CONCAT('%', #{query.brand}, '%')
AND a.production_year >= #{query.productionYearStart}
AND a.production_year <= #{query.productionYearEnd}
AND a.condition_level = #{query.conditionLevel}
AND a.status = #{query.status}
AND a.trace_no LIKE CONCAT('%', #{query.traceNo}, '%')
AND a.seller_id = #{query.sellerId}
ORDER BY a.create_time DESC
